import{_ as a,c as t,a2 as s,o as r}from"./chunks/framework.rHWNTPhC.js";const b=JSON.parse('{"title":"Broadcast-Service","description":"","frontmatter":{},"headers":[],"relativePath":"services/backend-services/broadcast-service/index.md","filePath":"services/backend-services/broadcast-service/index.md"}'),d={name:"services/backend-services/broadcast-service/index.md"};function n(i,e,o,c,h,l){return r(),t("div",null,e[0]||(e[0]=[s('<h1 id="broadcast-service" tabindex="-1">Broadcast-Service <a class="header-anchor" href="#broadcast-service" aria-label="Permalink to &quot;Broadcast-Service&quot;">​</a></h1><p>Dieser Service ermöglicht den Benutzern des Admin-Tools, eine Broadcast-Nachricht über die POST-Methode <code>broadcast()</code> an alle Wahllokale zu senden. Im <a href="/Wahllokalsystem/services/frontend-services/wahllokalsystem/">Frontend des Wahllokalsystems</a> prüft jedes Wahllokal in regelmäßigen Abständen mit der <code>getMessage()</code>-Methode, ob es neue, noch ungelesene Broadcast-Nachrichten gibt, die ihm zugewiesen wurden. Wenn dies der Fall ist, wird die Nachricht an das Wahllokal übermittelt. Nach der Empfangsbestätigung wird die entsprechende Nachricht für das betroffene Wahllokal über die POST-Methode <code>deleteMessage()</code> gelöscht.</p><h2 id="abhangigkeiten" tabindex="-1">Abhängigkeiten <a class="header-anchor" href="#abhangigkeiten" aria-label="Permalink to &quot;Abhängigkeiten&quot;">​</a></h2><p>Der Service hat keine Abhängigkeiten zu anderen Services.</p><h2 id="daten-und-funktionen" tabindex="-1">Daten und Funktionen <a class="header-anchor" href="#daten-und-funktionen" aria-label="Permalink to &quot;Daten und Funktionen&quot;">​</a></h2><h3 id="broadcastmessagedto" tabindex="-1">BroadcastMessageDTO <a class="header-anchor" href="#broadcastmessagedto" aria-label="Permalink to &quot;BroadcastMessageDTO&quot;">​</a></h3><p>Enthält die Nachricht und die IDs aller zu benachrichtigenden Wahllokalen.</p><h3 id="messagedto" tabindex="-1">MessageDTO <a class="header-anchor" href="#messagedto" aria-label="Permalink to &quot;MessageDTO&quot;">​</a></h3><p>Enthält die Nachricht eines einzelnen Wahllokals.</p><h3 id="post-methode-broadcast-broadcastmessagedto-broadcastmessagedto" tabindex="-1">Post-Methode broadcast(BroadcastMessageDTO broadcastMessageDTO) <a class="header-anchor" href="#post-methode-broadcast-broadcastmessagedto-broadcastmessagedto" aria-label="Permalink to &quot;Post-Methode broadcast(BroadcastMessageDTO broadcastMessageDTO)&quot;">​</a></h3><p>Mit dem Objekt <code>broadcastMessageDTO</code> erhält der Controller sowohl eine Textnachricht als auch eine ID-Liste aller adressierten Wahllokale. Das führt zur Speicherung der Text-Nachricht für jedes einzelne Wahllokal aus der Liste.</p><h3 id="get-methode-getmessage-string-wahlbezirkid" tabindex="-1">Get-Methode getMessage(String wahlbezirkID) <a class="header-anchor" href="#get-methode-getmessage-string-wahlbezirkid" aria-label="Permalink to &quot;Get-Methode getMessage(String wahlbezirkID)&quot;">​</a></h3><p>Sucht nach der ältesten Nachricht für die gegebene Wahlbezirk-Id und gibt diese zurück.</p><h3 id="post-methode-deletemessage-string-nachrichtid" tabindex="-1">Post-Methode deleteMessage(String nachrichtID) <a class="header-anchor" href="#post-methode-deletemessage-string-nachrichtid" aria-label="Permalink to &quot;Post-Methode deleteMessage(String nachrichtID)&quot;">​</a></h3><p>Löscht die Nachricht mit der gegebenen ID, nachdem sie gelesen wurde. Es wird nur der dem entsprechenden Wahllokal zugewiesene Datenbankeintrag gelöscht.</p>',15)]))}const m=a(d,[["render",n]]);export{b as __pageData,m as default};
